def inner_join(left, right, key):
    index = {}
    for r in right:
        index.setdefault(r[key], []).append(r)
    out = []
    for l in left:
        for r in index.get(l[key], []):
            merged = dict(l)
            merged.update(r)
            out.append(merged)
    return out

